{"file_path":"sales_dashboard/report.py","content":""""Product analytics dashboard: conversion statistics over customer sessions."""
from sales_dashboard.loader import daily_conversion_counts
from sales_dashboard.metrics import conversion_rate, conversions_in_window, pooled_conversion_rate


def campaign_summary(groups, days):
    """Summary of groups of sessions. See SPEC.md section 7."""
    all_events = [e for evts in groups.values() for e in evts]
    if all_events:
        first = min(e["day"] for e in all_events)
        last = max(e["day"] for e in all_events)
        recent = conversions_in_window(daily_conversion_counts(all_events, first, last), days)
    else:
        recent = 0
    return {
        "rate": round(pooled_conversion_rate(groups), 3),
        "recent": recent,
        "groups": sum(1 for events in groups.values() if events),
    }


def top_converting_groups(groups, n):
    """The groups with the highest conversion rate. See SPEC.md section 8."""
    ranked = sorted(
        (name for name, events in groups.items() if events),
        key=lambda name: (-conversion_rate(groups[name]), name),
    )
    return ranked[:n]
"}

{"file_path": "tests/test_metrics.py", "content": "import pytest

from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_conversion_rate_counts_none_in_denominator():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5


def test_conversion_rate_empty():
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_equal_groups():
    groups = {"a": [{"converted": True}, {"converted": False}], "b": [{"converted": True}, {"converted": False}]}
    assert pooled_conversion_rate(groups) == 0.5


def test_pooled_conversion_rate_weights_by_sessions():
    groups = {
        "a": [{"converted": True}],
        "b": [{"converted": False}, {"converted": None}, {"converted": False}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_conversion_rate_no_sessions(groups):
    assert pooled_conversion_rate(groups) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 6), (5, 7)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 4], days) == expected


def test_conversion_rate_by_group_orders_names_and_uses_none_for_empty_groups():
    groups = {"z": [{"converted": False}], "b": [], "a": [{"converted": True}]}
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", None), ("z", 0.0)]


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1], 0), ([1, 1, -1, 2, 3, 4, 0, 1], 3)],
)
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected
"}

{"file_path": "tests/test_loader.py", "content": "import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log


def test_parse_session_log_one_line():
    assert parse_session_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "converted": True}]


def test_parse_session_log_strips_fields_and_parses_flags():
    assert parse_session_log([" x1 , 3 , 1 ", " x2 , 4 , 0 ", " x3 , 5 ,  "]) == [
        {"id": "x1", "day": 3, "converted": True},
        {"id": "x2", "day": 4, "converted": False},
        {"id": "x3", "day": 5, "converted": None},
    ]


def test_parse_session_log_skips_blanks_and_comments():
    assert parse_session_log(["", " \t\n", "# comment", "  # x1,3,1", "x2,4,1"]) == [
        {"id": "x2", "day": 4, "converted": True},
    ]


@pytest.mark.parametrize("bad_line", ["x2,4", "x2,4,1,extra", "x2,not-an-integer,1"])
def test_parse_session_log_error_counts_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_session_log(["# comment", "x1,3,1", " \t", bad_line])


def test_dedupe_sessions_keeps_last_duplicate_and_sorts_by_day_then_id():
    first = {"id": "a", "day": 4, "converted": True}
    last = {"id": "a", "day": 2, "converted": False}
    same_day = {"id": "b", "day": 2, "converted": True}
    earlier_day = {"id": "c", "day": 1, "converted": None}
    assert dedupe_sessions([first, same_day, earlier_day, last]) == [earlier_day, last, same_day]


def test_daily_conversion_counts_includes_every_day_in_range():
    events = parse_session_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,2,", "f,4,1", "g,5,1"])
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 4, 1) == []
    assert daily_conversion_counts([], 1, 2) == [0, 0]
"}

